class Poll:
    def __init__(self, question: str) -> None:
        self.question = question
        self.options = []  # list of options in order added
        self.votes = {}    # voter -> option
        self.counts = {}   # option -> vote count

    def add_option(self, option: str) -> None:
        if option not in self.counts:
            self.options.append(option)
            self.counts[option] = 0

    def vote(self, voter: str, option: str) -> None:
        if option not in self.counts:
            raise ValueError(f"Option does not exist: {option}")
        if voter in self.votes:
            raise ValueError(f"Voter has already voted: {voter}")
        self.votes[voter] = option
        self.counts[option] += 1

    def winner(self) -> str | None:
        if len(self.votes) < 3:
            return None
        max_count = max(self.counts.values())
        if max_count == 0:
            return None
        # Iterate in reverse order of addition so last-added wins ties
        for option in reversed(self.options):
            if self.counts[option] == max_count:
                return option
        return None
